<?php

declare(strict_types=1);

namespace Rustine\Tests\Apply;

use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;
use Rustine\Apply\LockChange;
use Rustine\Apply\LockfileVersions;
use Rustine\Trivy\Ecosystem;

final class LockfileVersionsTest extends TestCase
{
    private const string CLASSIC = <<<'LOCK'
        # THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
        # yarn lockfile v1


        "@babel/core@^7.0.0", "@babel/core@^7.1.0":
          version "7.20.1"
          resolved "https://registry.yarnpkg.com/@babel/core/-/core-7.20.1.tgz#abc"
          dependencies:
            semver "^6.0.0"

        semver@^5.0.0:
          version "5.7.1"

        semver@^6.0.0:
          version "6.3.0"
        LOCK;

    private const string BERRY = <<<'LOCK'
        # This file is generated by running "yarn install" inside your project.

        __metadata:
          version: 8
          cacheKey: 10c0

        "@babel/core@npm:^7.0.0, @babel/core@npm:^7.1.0":
          version: 7.20.1
          resolution: "@babel/core@npm:7.20.1"
          dependencies:
            semver: "npm:^6.0.0"
          languageName: node
          linkType: hard

        "resolve@patch:resolve@npm%3A^1.1.7#optional!builtin<compat/resolve>":
          version: 1.22.8
          resolution: "resolve@patch:resolve@npm%3A1.22.8#optional!builtin<compat/resolve>::version=1.22.8&hash=c3c19d"
          languageName: node
          linkType: hard

        "app@workspace:.":
          version: 0.0.0-use.local
          resolution: "app@workspace:."
          languageName: unknown
          linkType: soft
        LOCK;

    #[Test]
    public function itReadsYarnClassicLockfiles(): void
    {
        $versions = new LockfileVersions()->parse(Ecosystem::Yarn, self::CLASSIC);

        $this->assertSame(['@babel/core' => ['7.20.1'], 'semver' => ['5.7.1', '6.3.0']], $versions);
    }

    #[Test]
    public function itFilesAliasesUnderTheirRealPackageName(): void
    {
        $classic = "\"string-width-cjs@npm:string-width@^4.2.0\":\n  version \"4.2.3\"\n";
        $berry = "\"@scope/alias@npm:@real/pkg@^1.0.0\":\n  version: 1.4.0\n  resolution: \"@real/pkg@npm:1.4.0\"\n";

        $this->assertSame(
            ['string-width' => ['4.2.3']],
            new LockfileVersions()->parse(Ecosystem::Yarn, $classic),
        );
        $this->assertSame(['@real/pkg' => ['1.4.0']], new LockfileVersions()->parse(Ecosystem::Yarn, $berry));
    }

    #[Test]
    public function itReadsYarnBerryLockfilesAndIgnoresTheWorkspaces(): void
    {
        $versions = new LockfileVersions()->parse(Ecosystem::Yarn, self::BERRY);

        $this->assertSame(['@babel/core' => ['7.20.1'], 'resolve' => ['1.22.8']], $versions);
    }

    #[Test]
    public function itReadsComposerLockfilesDevPackagesIncluded(): void
    {
        $lock = json_encode([
            'packages'     => [
                ['name' => 'symfony/console', 'version' => 'v6.4.1'],
                ['name' => 'twig/twig', 'version' => '3.8.0'],
            ],
            'packages-dev' => [['name' => 'phpunit/phpunit', 'version' => '12.0.0']],
        ], \JSON_THROW_ON_ERROR);

        $this->assertSame(
            ['phpunit/phpunit' => ['12.0.0'], 'symfony/console' => ['v6.4.1'], 'twig/twig' => ['3.8.0']],
            new LockfileVersions()->parse(Ecosystem::Composer, $lock),
        );
    }

    #[Test]
    public function anUnreadableComposerLockfileHasNoPackage(): void
    {
        $this->assertSame([], new LockfileVersions()->parse(Ecosystem::Composer, 'not json'));
    }

    #[Test]
    public function itReportsChangedAddedAndRemovedPackages(): void
    {
        $before = json_encode([
            'packages' => [
                ['name' => 'a/a', 'version' => '1.0.0'],
                ['name' => 'b/b', 'version' => '2.0.0'],
                ['name' => 'c/c', 'version' => '3.0.0'],
            ],
        ], \JSON_THROW_ON_ERROR);
        $after = json_encode([
            'packages' => [
                ['name' => 'a/a', 'version' => '1.0.1'],
                ['name' => 'b/b', 'version' => '2.0.0'],
                ['name' => 'd/d', 'version' => '4.0.0'],
            ],
        ], \JSON_THROW_ON_ERROR);

        $changes = new LockfileVersions()->changes(Ecosystem::Composer, $before, $after);

        $this->assertSame(
            [['a/a', ['1.0.0'], ['1.0.1']], ['c/c', ['3.0.0'], []], ['d/d', [], ['4.0.0']]],
            array_map(static fn(LockChange $c): array => [$c->package, $c->before, $c->after], $changes),
        );
    }

    #[Test]
    public function aPackageInSeveralVersionsOnlyReportsTheOnesThatMoved(): void
    {
        $before = "semver@^5.0.0:\n  version \"5.7.1\"\n\nsemver@^6.0.0:\n  version \"6.3.0\"\n";
        $after = "semver@^5.0.0:\n  version \"5.7.2\"\n\nsemver@^6.0.0:\n  version \"6.3.0\"\n";

        $changes = new LockfileVersions()->changes(Ecosystem::Yarn, $before, $after);

        $this->assertCount(1, $changes);
        $this->assertSame(['5.7.1'], $changes[0]->before);
        $this->assertSame(['5.7.2'], $changes[0]->after);
    }

    #[Test]
    public function aLockfileThatDidNotChangeHasNoChange(): void
    {
        $this->assertSame([], new LockfileVersions()->changes(Ecosystem::Yarn, self::BERRY, self::BERRY));
    }
}
